import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { defaultSettings } from "../simulator";
import {
  FLOW_VARIANTS,
  buildCatalog,
  confirmPlot,
  createGuideEnv,
  decideLogin,
  initialState,
  isFlowVariant,
  loadShippedFlow,
  parseFlows,
  projectLogin,
  restoreState,
  runOne,
  scriptKnobs,
  toInput,
  type FlowsFile,
} from "./index";

// The two-plot flow (players with only Plots 1 and 2): same farms and layouts as the three-plot
// flow, with Plot 3's work done on Plot 1. Generated by tools/rose-dragon with ROSE_PLOTS=2.

const guideEnv = createGuideEnv();
const read = (url: string): FlowsFile => parseFlows(readFileSync(`public${url}`, "utf8"));
const two = read(FLOW_VARIANTS.two.url);
const three = read(FLOW_VARIANTS.three.url);
const catalog = buildCatalog(two, guideEnv.env.resolveLayout);
const SUPPLIES = { dead_plant: 250, fermento: 50 };

describe("the two-plot flow", () => {
  it("has Plots 1 and 2, each with its own script, and the same goal", () => {
    expect(two.plots.map((p) => p.id)).toEqual([1, 2]);
    expect(two.plots.every((p) => p.script?.source.includes("Rose Dragon, Plot"))).toBe(true);
    expect(catalog.goal).toEqual(buildCatalog(three, guideEnv.env.resolveLayout).goal);
    expect(scriptKnobs(two)).toEqual(scriptKnobs(three));
  });

  it("offers every farm of the three-plot flow, with the same layouts", () => {
    const codes = (f: FlowsFile) => new Map(f.plots.flatMap((p) => p.flow.steps.map((s) => [s.id, "code" in s.layout ? s.layout.code : ""] as const)));
    const twoSteps = new Set(two.plots.flatMap((p) => p.flow.steps.map((s) => s.id)));
    for (const id of codes(three).keys()) expect(twoSteps.has(id)).toBe(true);
    // Plot 3's farms move to Plot 1 unchanged (Plots 1 and 3 have the same shape).
    const plot3 = three.plots.find((p) => p.id === 3)!;
    const plot1 = two.plots.find((p) => p.id === 1)!;
    for (const id of ["soggybud", "pt", "shellfruit", "commons"]) {
      const a = plot3.flow.steps.find((s) => s.id === id)!.layout;
      const b = plot1.flow.steps.find((s) => s.id === id)!.layout;
      expect(b).toEqual(a);
    }
  });

  it("decides both plots in login order against shared stock", () => {
    const outcomes = decideLogin(two, toInput(initialState(two, defaultSettings(), SUPPLIES)), guideEnv);
    expect(outcomes.map((o) => o.plotId)).toEqual([1, 2]);
    expect(outcomes[1].inventoryBefore).toEqual(outcomes[0].inventoryAfter);
    for (const o of outcomes) expect(o.to).not.toBe("hub");
    const { state } = projectLogin(two, toInput(initialState(two, defaultSettings(), SUPPLIES)), guideEnv);
    expect(state.summary.debtEvents).toBe(0);
    const after = confirmPlot(initialState(two, defaultSettings(), SUPPLIES), outcomes[0]);
    expect(decideLogin(two, toInput(after), guideEnv).map((o) => o.plotId)).toEqual([2]);
  });

  it("plays to Done without debt", () => {
    const run = runOne(two, toInput(initialState(two, defaultSettings(), SUPPLIES)), 1, guideEnv);
    expect(run.done).toBe(true);
    expect(run.debtEvents).toBe(0);
    expect(Object.keys(run.farms)).toEqual(["1", "2"]);
  }, 120_000);

  it("does not restore a three-plot save into the two-plot flow's Plot 3", () => {
    const saved = { version: 3, ...initialState(three, defaultSettings(), SUPPLIES) };
    const restored = restoreState(JSON.parse(JSON.stringify(saved)), two, catalog, defaultSettings())!;
    expect(Object.keys(restored.plots)).toEqual(["1", "2"]);
  });
});

describe("flow variants", () => {
  it("loads the chosen version", async () => {
    const urls: string[] = [];
    const fake = (async (url: string) => {
      urls.push(url);
      return new Response(readFileSync(`public${url}`, "utf8"));
    }) as unknown as typeof fetch;
    expect((await loadShippedFlow("two", fake)).plots).toHaveLength(2);
    expect((await loadShippedFlow("three", fake)).plots).toHaveLength(3);
    expect(urls).toEqual([FLOW_VARIANTS.two.url, FLOW_VARIANTS.three.url]);
    expect(isFlowVariant("two")).toBe(true);
    expect(isFlowVariant("four")).toBe(false);
  });
});
